class BlackboxStructureError(Exception):
    """
    Raised when specific blackbox structure does not have mandatory items.
    """
    pass


class BlackboxSocVersionError(Exception):
    """
    Raised when SOC version is not found in blackbox file or SOC family version from blackbox file is not as expected.
    """
    pass


